  feedback_summary_student = 'Небольшой художественный вуз с сильными педагогами-практиками из ГТГ, Кремля и ГМИИ, камерная атмосфера, где все друг друга знают. Заметная и повторяющаяся критика — крайне плотное расписание (пары с 9 утра до вечера), отмена занятий предупреждается за считанные минуты, отсутствие общежития и отдельные случаи резкого, унизительного отношения преподавателей к студентам.',
  feedback_positive_highlights = '{"педагоги-практики из ведущих музеев страны","камерная, дружеская атмосфера"}',
  feedback_negative_highlights = '{"крайне плотное расписание без свободного времени","отсутствие общежития","случаи резкого отношения части преподавателей"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Российская академия живописи, ваяния и зодчества Ильи Глазунова' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Одна из самых высоко оцениваемых экономических магистратур страны: подавляющее большинство студентов довольны образованием и профессорами-практиками мирового уровня. Единственная последовательная критика — очень высокая учебная нагрузка, из-за которой студентам советуют на время учёбы отказаться от работы.',
  feedback_positive_highlights = '{"профессора мирового уровня","высочайшая удовлетворённость выпускников качеством обучения"}',
  feedback_negative_highlights = '{"очень высокая учебная нагрузка, несовместимая с работой"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Российская экономическая школа' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Крупный и узнаваемый экономический вуз с активной студенческой жизнью и поддержкой между курсами. Отзывы сильно зависят от конкретного преподавателя и факультета: часть студентов довольна знаниями и трудоустройством, другая часть критикует соотношение качества образования и стоимости обучения, а также ежегодные изменения условий оплаты в общежитиях.',
  feedback_positive_highlights = '{"активная студенческая жизнь","реальные истории трудоустройства выпускников"}',
  feedback_negative_highlights = '{"неровное качество преподавания по факультетам","жалобы на изменение условий оплаты общежитий"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Российский экономический университет имени Г.В. Плеханова' and city = 'Москва';
